package ru.oopssre.gremlinamp;
import android.content.Context;import android.net.*;import java.nio.file.*;import java.io.*;import java.time.*;import java.util.*;import org.json.*;
public class FeatureChecks {
 static int checks;static void check(boolean b,String msg){checks++;if(!b)throw new AssertionError(msg);}
 static JSONObject game(String id,String title,int year,String genre)throws Exception {return new JSONObject().put("_music_contract",1).put("id",id).put("title",title).put("year",year).put("platform","nes").put("platform_label","NES").put("manifest","music/sets/"+id+".json").put("terms",new JSONObject().put("genre",new JSONObject().put(genre,genre)));}
 static void cache(Library l,String path,JSONObject obj)throws Exception {Library.atomic(l.jsonFile(Library.BASE+path),obj.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 public static void main(String[] args)throws Exception {
  Context ctx=new Context(Files.createTempDirectory("amp-test").toFile());Library l=new Library(ctx);
  check(!NetworkPolicy.allowed(ctx,"any"),"offline");NetworkCapabilities net=new NetworkCapabilities();net.internet=true;net.cellular=true;ctx.cm.caps=net;
  check(!NetworkPolicy.allowed(ctx,"wifi"),"no mobile for wifi");check(NetworkPolicy.allowed(ctx,"any"),"mobile enabled");net.wifi=true;net.cellular=false;check(NetworkPolicy.allowed(ctx,"wifi"),"wifi");net.cellular=true;check(!NetworkPolicy.allowed(ctx,"wifi"),"no mixed cellular leak");net.cellular=false;
  long before=Instant.parse("2026-11-01T03:00:00Z").toEpochMilli();check(SyncRules.untilMorning(before)==3600000,"07 Moscow");check(SyncRules.untilMorning(before+3600000)==86400000,"next day at exact 07");
  byte[] bytes={1,2,3};String hash=Library.hash(bytes);JSONObject a=new JSONObject().put("sha256",hash).put("bytes",3).put("format","nsf").put("url","../files/test.nsf");JSONObject track=new JSONObject().put("asset",a).put("play_ms",14000).put("duration_known",true).put("backend","gme");
  JSONObject g=game("game-ra-1","One",1990,"action"),later=game("game-ra-2","Two",1992,"action"),earlier=game("game-ra-3","Three",1988,"rpg"),other=game("game-ra-4","Four",1993,"rpg");JSONObject manifest=new JSONObject().put("tracks",new JSONArray().put(track));
  cache(l,g.getString("manifest"),manifest);check(l.downloadLabel(g).equals("Скачать"),"initial missing");Library.atomic(l.assetFile(a),bytes);check(l.fullyLocal(g),"cached files available");l.markComplete(g,manifest);check(l.downloadLabel(g).equals("Ожидание"),"legacy artwork is prepared automatically");check(l.savedGames().size()==1,"saved game metadata");
  JSONObject extra=new JSONObject(a.toString()).put("sha256",Library.hash(new byte[]{4})).put("bytes",1);manifest.getJSONArray("tracks").put(new JSONObject(track.toString()).put("asset",extra));cache(l,g.getString("manifest"),manifest);check(l.fullyLocal(g)&&l.localCounts(g)[0]<l.localCounts(g)[1],"new file requires download while prior snapshot remains playable");check(l.downloadLabel(g).equals("Обновить"),"saved collection update");check(l.remaining(Collections.singletonList(g))==1,"only missing bytes");
  l.assetFile(a).delete();check(l.remaining(Collections.singletonList(g))==4,"deleted file detected");Library.atomic(l.assetFile(a),new byte[]{1});check(!l.available(a),"truncated file not complete");Library.atomic(l.assetFile(a),bytes);Library.atomic(l.assetFile(extra),new byte[]{4});
  JSONObject gameIndex=ContractFixtures.group(ContractFixtures.index(g,later,earlier,other),"s","game-ra-1","game-ra-2","game-ra-3");cache(l,"music/game-index.json",gameIndex);
  JSONArray editions=new JSONArray();for(JSONObject row:List.of(g,later,earlier,other)){JSONObject e=new JSONObject(row.toString()).put("ra_id",Long.parseLong(row.getString("id").substring(8)));editions.put(e);cache(l,row.getString("manifest"),new JSONObject().put("tracks",new JSONArray().put(track)));Library.atomic(l.assetFile(a),bytes);l.markComplete(row,manifest);}
  JSONArray members=new JSONArray().put(new JSONObject().put("ra_id",1)).put(new JSONObject().put("ra_id",2)).put(new JSONObject().put("ra_id",3));JSONArray series=new JSONArray().put(new JSONObject().put("id","s").put("name","Test").put("members",members));cache(l,"assets/statistics.json",new JSONObject().put("editions",editions).put("series",series));
  Set<String> played=new HashSet<>(Set.of("game-ra-1"));l.preferences.edit().putString("after_album","series").apply();List<JSONObject> choices=Continuation.candidates(l,g,played);check(choices.size()==2,"series members only");check(choices.get(0).getString("id").equals("game-ra-2"),"chronological successor");played.add("game-ra-2");check(Continuation.candidates(l,g,played).get(0).getString("id").equals("game-ra-3"),"no game repeats");
  check(Continuation.candidates(l,g,played,"other-series").isEmpty(),"an explicit series cannot switch to an overlapping series");
  check(Continuation.candidates(l,other,Set.of()).isEmpty(),"a standalone game cannot continue by series");
  l.preferences.edit().putString("after_album","library").apply();
  check(Continuation.candidates(l,g,played).stream().anyMatch(row->row.optString("id").equals("game-ra-4")),"library continuation includes standalone games");
  check(!Continuation.candidates(l,other,Set.of(other.getString("id"))).isEmpty(),"a standalone game can continue through the library");
  l.preferences.edit().putString("after_album","genre").apply();check(Continuation.candidates(l,g,played).isEmpty(),"genre strict");played.remove("game-ra-2");check(Continuation.candidates(l,g,played).size()==1,"genre match");l.preferences.edit().putString("after_album","similar").apply();check(Continuation.candidates(l,g,played).get(0).getString("id").equals("game-ra-2"),"similar prioritizes series and genre");
  l.preferences.edit().putString("year_filter","1993").apply();check(Continuation.candidates(l,g,played).isEmpty(),"year filter retained");l.preferences.edit().putString("year_filter","").apply();l.assetFile(a).delete();check(Continuation.candidates(l,g,played).isEmpty(),"local only excludes missing files");
  l.trackSeries("s");check(l.preferences.getStringSet("saved_series",Set.of()).contains("s"),"series subscription");
  Set<Integer> visited=new HashSet<>(Set.of(0));Random random=new Random(1);for(int n=0;n<2;n++){int next=ContinuationRules.nextIndex(0,3,visited,true,false,random);check(!visited.contains(next),"shuffle no repeats");visited.add(next);}check(ContinuationRules.nextIndex(0,3,visited,true,false,random)==-1,"shuffle eventually ends");check(ContinuationRules.nextIndex(2,3,visited,false,true,random)==0,"repeat queue priority");
  check(ContinuationRules.score("genre",false,Set.of(),Set.of(),true)==0,"missing genres not similarity");
  // Exercise the real sync selection, download loop and saved markers with a fake transport.
  class Remote extends Library {
   Map<String,JSONObject> remote=new HashMap<>();Map<String,byte[]> content=new HashMap<>();int transfers;
   Remote(Context c){super(c);}
   JSONObject onlineJson(String url)throws Exception {JSONObject obj=remote.get(url);if(obj==null)throw new IOException("HTTP 404");return new JSONObject(obj.toString());}
   JSONObject json(String url,boolean refresh)throws Exception{return remote.containsKey(url)?freshJson(url):super.json(url,refresh);}
   JSONObject freshJson(String url)throws Exception {JSONObject obj=remote.get(url);if(obj==null)throw new IOException("fixture missing "+url);atomic(jsonFile(url),obj.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));return new JSONObject(obj.toString());}
   File fetch(JSONObject m,JSONObject asset)throws Exception {File f=assetFile(asset);if(!available(asset)){transfers++;atomic(f,content.get(asset.getString("sha256")));}return f;}
   void measureTrack(JSONObject t){}
   File cover(JSONObject g){return new File(root,"missing");}
   File picture(JSONObject item,boolean series,boolean preview){return new File(root,"missing");}
  }
  Remote remote=new Remote(new Context(Files.createTempDirectory("amp-sync").toFile()));JSONObject oldGame=game("game-ra-11","Saved",1990,"action"),added=game("game-ra-12","New series game",1991,"action"),unrelated=game("game-ra-13","Other",1992,"rpg");
  byte[] b1={5},b2={6},b3={7};JSONObject oldAsset=new JSONObject(a.toString()).put("sha256",Library.hash(b1)).put("bytes",1),newAsset=new JSONObject(oldAsset.toString()).put("sha256",Library.hash(b2)),thirdAsset=new JSONObject(oldAsset.toString()).put("sha256",Library.hash(b3));
  remote.content.put(Library.hash(b1),b1);remote.content.put(Library.hash(b2),b2);remote.content.put(Library.hash(b3),b3);Library.atomic(remote.assetFile(oldAsset),b1);remote.markComplete(oldGame,new JSONObject());remote.trackSeries("follow");
  remote.remote.put(MusicContract.INDEX,ContractFixtures.group(ContractFixtures.index(oldGame,added,unrelated),"follow","game-ra-11","game-ra-12"));
  JSONArray remoteSeries=new JSONArray().put(new JSONObject().put("id","follow").put("name","Follow").put("members",new JSONArray().put(new JSONObject().put("ra_id",11)).put(new JSONObject().put("ra_id",12))));remote.remote.put(Library.BASE+"assets/statistics.json",new JSONObject().put("series",remoteSeries).put("editions",new JSONArray()));
  remote.remote.put(Library.BASE+oldGame.getString("manifest"),new JSONObject().put("tracks",new JSONArray().put(new JSONObject(track.toString()).put("asset",oldAsset)).put(new JSONObject(track.toString()).put("asset",newAsset))));remote.remote.put(Library.BASE+added.getString("manifest"),new JSONObject().put("tracks",new JSONArray().put(new JSONObject(track.toString()).put("asset",newAsset))));remote.remote.put(Library.BASE+unrelated.getString("manifest"),new JSONObject().put("tracks",new JSONArray().put(new JSONObject(track.toString()).put("asset",thirdAsset))));
  remote.syncSaved(message->{});check(remote.transfers==1,"sync only transfers one shared new file");check(remote.subscribed(added),"new series game downloaded");check(!remote.subscribed(unrelated),"unrelated game not downloaded");check(remote.assetFile(oldAsset).isFile(),"existing music retained");remote.syncSaved(message->{});check(remote.transfers==1,"unchanged sync transfers no music");remote.preferences.edit().putBoolean("follow_all_music",true).apply();remote.syncSaved(message->{});check(!remote.subscribed(unrelated)&&remote.transfers==1,"whole ZIP requires explicit action before automatic refresh");
  remote.remote.put(MusicContract.INDEX,ContractFixtures.group(ContractFixtures.index(oldGame,added,unrelated),"follow","game-ra-11","game-ra-12","game-ra-13"));remote.syncSaved(message->{});check(remote.subscribed(unrelated)&&remote.transfers==2,"new game from followed series is saved");
  remote.preferences.edit().putStringSet("paused_downloads",Set.of(unrelated.getString("id"))).apply();remote.assetFile(thirdAsset).delete();remote.syncSaved(message->{});check(!remote.assetFile(thirdAsset).isFile(),"automatic music refresh respects explicit pause");remote.resumeRequests();remote.syncSaved(message->{});check(remote.assetFile(thirdAsset).isFile(),"explicit update request resumes paused music");
  System.out.println(checks+" feature checks passed: inventory, network, scheduling, continuation and updates");
 }
}
